import {Chess} from './vendor/chess.js';
export const LEVELS={1:{name:'Deadfish',depth:2,budget:220,delay:350},2:{name:'Little Fish',depth:2,budget:350,delay:450},3:{name:'Big Fish',depth:4,budget:900,delay:700},4:{name:'Razor Teeth',depth:8,budget:1600,delay:900},5:{name:'Cyber Tank',depth:10,budget:2400,delay:1100}};
export const CONTROLS={'1':{name:'1 minute',seconds:60,increment:0},'0':{name:'Untimed',seconds:0,increment:0},'5':{name:'5 minutes',seconds:300,increment:0},'10':{name:'10 minutes',seconds:600,increment:0},'15+10':{name:'15 minutes + 10 seconds',seconds:900,increment:10},'30':{name:'30 minutes',seconds:1800,increment:0}};
export const ENDGAMES=[
{id:'queen-box',name:'King & queen',fen:'7k/8/5K2/8/4Q3/8/8/8 w - - 0 1',tip:'Use your queen to shrink the king’s space. Bring your king closer, then give mate. Leave a legal move if you are not giving check.'},
{id:'rook-box',name:'King & rook',fen:'7k/8/5K2/8/8/8/8/R7 w - - 0 1',tip:'Use your rook to cut off a rank or file. Bring your king close enough to cover escape squares, then check along the edge.'},
{id:'pawn-race',name:'Promote a pawn',fen:'6k1/8/3PK3/8/8/8/8/8 w - - 0 1',tip:'Keep your king in front of the pawn when it needs protection. Reach the last rank, promote, then finish with checkmate.'}
];
export function gameFrom(record,limit=record.moves.length){const c=record.fen?new Chess(record.fen):new Chess();for(const m of record.moves.slice(0,limit))c.move(m);return c}
export function settleClock(m,now=Date.now()){if(!m||!m.clock||m.paused||m.result||!m.runningSince)return false;const side=m.turn||'w';m.clock[side]=Math.max(0,m.clock[side]-(now-m.runningSince)/1000);m.runningSince=now;if(m.clock[side]===0){const c=gameFrom(m);const winner=side==='w'?'b':'w';const bareKing=c.board().flat().filter(Boolean).filter(p=>p.color===winner).every(p=>p.type==='k');m.result=bareKing?'draw':side==='w'?'loss':'win';m.reason=bareKing?'Time expired; opponent has only a king':'Time expired';return true}return false}
export function commitMove(m,move,now=Date.now()){if(settleClock(m,now)||m.result||m.paused)return null;const c=gameFrom(m),side=c.turn(),played=c.move(move);m.moves=c.history();if(m.clock)m.clock[side]+=m.increment||0;m.turn=c.turn();m.runningSince=now;if(c.isGameOver()){m.result=c.isCheckmate()?(c.turn()==='b'?'win':'loss'):'draw';m.reason=c.isCheckmate()?'Checkmate':c.isStalemate()?'Stalemate':c.isThreefoldRepetition()?'Threefold repetition':c.isInsufficientMaterial()?'Insufficient material':'Draw'}return played}
const worth={p:1,n:3,b:3,r:5,q:9,k:0};
export function moveNotes(record){const c=record.fen?new Chess(record.fen):new Chess(),rows=[];for(const san of record.moves){const before=c.fen(),m=c.move(san);let text=m.color==='w'?'You moved':'Computer moved';text+=' '+({p:'the pawn',n:'the knight',b:'the bishop',r:'the rook',q:'the queen',k:'the king'}[m.piece])+' from '+m.from+' to '+m.to+'.';if(m.captured)text+=' Captured a '+({p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen'}[m.captured])+'.';if(c.isCheckmate())text+=' Checkmate: there is no legal escape.';else if(c.isStalemate())text+=' Stalemate: no legal moves, but the king is not in check.';else if(c.inCheck())text+=' The next move must answer the check.';if(m.isKingsideCastle()||m.isQueensideCastle())text+=' Castling moves the king and rook together.';if(m.promotion)text+=' The pawn promoted.';const exposed=c.board().flat().filter(p=>p&&p.color===m.color&&p.type!=='k'&&c.isAttacked(p.square,m.color==='w'?'b':'w')&&!c.isAttacked(p.square,m.color)).map(p=>p.square);if(exposed.length)text+=' Check these attacked, undefended pieces: '+exposed.join(', ')+'.';rows.push({san:m.san,color:m.color,before,fen:c.fen(),text,exposed,captured:m.captured||null,points:worth[m.captured]||0,from:m.from,to:m.to});}return rows}
export function gameSummary(record){const rows=moveNotes(record),white=rows.filter(r=>r.color==='w');return {checks:white.filter(r=>/[+#]/.test(r.san)).length,captured:white.reduce((n,r)=>n+r.points,0),lost:rows.filter(r=>r.color==='b').reduce((n,r)=>n+r.points,0),exposed:white.filter(r=>r.exposed.length).length,castled:white.some(r=>r.san.startsWith('O-O')),rows};}

export function botTiming(level,clock,increment=0){const config=LEVELS[level]||LEVELS[2];if(!clock)return {budget:config.budget,delay:config.delay};const seconds=Math.max(0,clock.b),fraction=Math.min(1,seconds/60);const delay=seconds<=10?Math.min(150,seconds*10):Math.round(config.delay*fraction);const budget=seconds<=10?Math.max(10,Math.min(100,seconds*10)):Math.max(50,Math.min(config.budget,seconds*1000/40+Math.min(increment*300,seconds*10)));return {budget:Math.floor(budget),delay:Math.floor(delay)}}
export function resultMessage(m){const title=m.result==='win'?'You won!':m.result==='loss'?'Computer won':'Draw';let explanation=m.reason||'The game has ended.';if(m.reason==='Time expired')explanation=m.result==='win'?'The computer ran out of time.':m.result==='loss'?'You ran out of time.':'Time ran out.';else if(m.reason==='Checkmate')explanation=m.result==='win'?'You checkmated the computer.':'The computer checkmated your king.';else if(m.reason==='Stalemate')explanation='Stalemate: the player to move has no legal moves, but their king is not in check.';else if(m.reason==='Threefold repetition')explanation='The same position occurred three times.';else if(m.reason==='Insufficient material')explanation='Neither side has enough material to give checkmate.';else if(m.reason==='Time expired; opponent has only a king')explanation='Time ran out, but the opponent has only a king, so the game is drawn.';return {title,explanation}}

export function executePremove(m,now=Date.now()){const move=m.premove;if(!move||m.result||m.paused)return false;if(gameFrom(m).turn()!=='w')return false;delete m.premove;try{return !!commitMove(m,move,now)}catch{return false}}
